Method.Implementation:
	set stat = $$$OK
	set pName="ITF Source Control"

    set pLink = "/csp/healthshare/itfcommon/IHC.ITF.SrcCtrlPkg.Login.cls"

    set stat =  ##class(%CSP.Portal.Utils).%AddFavorite(pName,pLink)
    if $$$ISERR(stat)
   		{
	   		Write !, "!!!! Can't create Favorite for: " _ pLink
   		}
   		else
   		{
	   		Write !, "Successfully created Favorite: " _ pName
   		}
   		return stat

	set stat = $$$OK
	 set r=##class(%SOAP.WSDL.Reader).%New() 
     set url="/WORK/common/class/IHC.ITF.SrcCtrlPkg.SrcCtrlDeploymentWS.WSDL"
     If ##class(%File).Exists(url)
     {
   		set stat = r.Process(url)
   		if $$$ISERR(stat)
   		{
	   		Write !, "!!!! Can't create Web client for: " _ url
   		}
   		else
   		{
	   		Write !, "Successfully created web link"
   		}
     }
     else
     {
	     Write !, "!!!! Can't find file: " _ url
     }
     return stat
